Section SELGP2.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.

(* [comment removed for export] *)
Local Ltac ocell_facts RT AF Σ m ART0 OPT p OWN PLO :=
  let OWNF := fresh "OWNF" in let P0 := fresh "P0" in let P8 := fresh "P8" in
  pose proof OPT as (OWNF & P0 & P8 & _ & _);
  assert (OWN : accok (rt_live RT Σ) (rt_frames RT Σ) m p 4) by (right; exact OWNF);
  assert (PLO : p + 4 <= rt_sp0 RT Σ - STACK_WIN)
    by (destruct OWNF as (f & k & Hin & H1 & H2 & _); pose proof (af_frames_range RT AF Σ m f k ART0 Hin) as (_ & R & _); clear - H1 H2 R; lia).
Local Ltac ocell_apart RT AF Σ m ART0 OPT p c n CIN AP :=
  assert (AP : p + 4 <= c \/ c + n <= p)
    by (let OWNF := fresh "OWNF" in pose proof OPT as (OWNF & _);
        destruct OWNF as (f & k & Hin & H1 & H2 & _); pose proof (af_frames_range RT AF Σ m f k ART0 Hin) as (_ & _ & _ & R);
        specialize (R c n CIN); clear - H1 H2 R; lia).

Theorem selGetParameters_sxsy_ok : selGetParameters_sxsy_cps RT.
